# qx_loan_payment :: (100000, 0.05, 30)
def qx_loan_payment(principal, annual_rate, years):
    r = annual_rate / 12
    n = years * 12
    if r == 0: return principal / n
    return principal * r * (1 + r) ** n / ((1 + r) ** n - 1)

if __name__ == '__main__':
    print(qx_loan_payment((100000, 0.05, 30)))

